<?php
declare(strict_types=1);
/* WEBSAZA_PLATFORM_V4 */
function ws_dir():string{return defined('D')?(string)constant('D'):__DIR__.'/_data';}
function ws_now():string{return date('Y-m-d H:i:s');}
function ws_raw_read(string $f):array{$x=json_decode((string)@file_get_contents($f),true);return is_array($x)?$x:[];}
function ws_raw_write(string $f,array $x):bool{$dir=dirname($f);if(!is_dir($dir))@mkdir($dir,0750,true);$l=@fopen($f.'.lock','c');if(!$l||!flock($l,LOCK_EX))return false;try{$t=$f.'.tmp.'.bin2hex(random_bytes(3));$q=json_encode($x,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);if($q===false||@file_put_contents($t,$q,LOCK_EX)===false)return false;@chmod($t,0640);return @rename($t,$f);}finally{flock($l,LOCK_UN);fclose($l);}}
function ws_list(array $x):bool{$i=0;foreach($x as $k=>$_)if($k!==$i++)return false;return true;}
function ws_bucket(string $f):string{return basename($f,'.json');}
function ws_managed(string $f):bool{return in_array(ws_bucket($f),['branches','leads','assignments','events','referral_rewards','finance_payments','finance_remittances','finance_feedback','sms_queue','sms_log','manager_reports'],true);}
function ws_finance_bucket(string $b):bool{return in_array($b,['finance_payments','finance_remittances','finance_feedback','referral_rewards'],true);}
function ws_db():?PDO{static $db=null,$done=false;if($done)return $db;$done=true;$dir=ws_dir();if(!is_dir($dir))@mkdir($dir,0750,true);if(!class_exists('PDO')||!in_array('sqlite',PDO::getAvailableDrivers(),true))return null;try{$db=new PDO('sqlite:'.$dir.'/websaza.sqlite3');$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$db->exec('PRAGMA journal_mode=WAL');$db->exec('PRAGMA synchronous=NORMAL');$db->exec('PRAGMA foreign_keys=ON');$db->exec('PRAGMA busy_timeout=5000');$db->exec('CREATE TABLE IF NOT EXISTS ds_meta(bucket TEXT PRIMARY KEY,kind TEXT,updated_at TEXT)');$db->exec('CREATE TABLE IF NOT EXISTS ds_rows(bucket TEXT,item_key TEXT,seq INTEGER,payload TEXT,PRIMARY KEY(bucket,item_key))');$db->exec('CREATE INDEX IF NOT EXISTS ds_seq ON ds_rows(bucket,seq)');$db->exec('CREATE TABLE IF NOT EXISTS contacts(phone TEXT PRIMARY KEY,first_seen_at TEXT,last_seen_at TEXT,last_status TEXT,last_lead_id TEXT,business TEXT,source TEXT,do_not_contact INTEGER DEFAULT 1,contact_count INTEGER DEFAULT 0,meta_json TEXT DEFAULT "{}")');$db->exec('CREATE INDEX IF NOT EXISTS contacts_last_seen ON contacts(last_seen_at)');$db->exec('CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT,kind TEXT,ref_id TEXT,phone TEXT,payload TEXT,created_at TEXT)');$db->exec('CREATE INDEX IF NOT EXISTS audit_created ON audit(created_at)');$db->exec('CREATE INDEX IF NOT EXISTS audit_kind_ref ON audit(kind,ref_id)');$db->exec('CREATE TABLE IF NOT EXISTS finance_ledger(id INTEGER PRIMARY KEY AUTOINCREMENT,bucket TEXT,item_key TEXT,action TEXT,before_hash TEXT,after_json TEXT,created_at TEXT)');$db->exec('CREATE INDEX IF NOT EXISTS finance_ledger_created ON finance_ledger(created_at)');$db->exec('CREATE INDEX IF NOT EXISTS finance_ledger_ref ON finance_ledger(bucket,item_key)');@chmod($dir.'/websaza.sqlite3',0640);return $db;}catch(Throwable $e){$db=null;return null;}}
function ws_row_key(array $r,int $i):string{$k=(string)($r['id']??'');return $k!==''?$k:'row_'.$i.'_'.substr(hash('sha256',json_encode($r,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES).$i),0,12);}
function ws_ledger(PDO $db,string $bucket,string $key,string $action,string $before,string $after):void{if(!ws_finance_bucket($bucket))return;$st=$db->prepare('INSERT INTO finance_ledger(bucket,item_key,action,before_hash,after_json,created_at) VALUES(?,?,?,?,?,?)');$st->execute([$bucket,$key,$action,$before!==''?hash('sha256',$before):'',$after,ws_now()]);}
function ws_store_write_tx(PDO $db,string $f,array $x):bool{$b=ws_bucket($f);$kind=ws_list($x)?'list':'map';$old=[];$st=$db->prepare('SELECT item_key,seq,payload FROM ds_rows WHERE bucket=?');$st->execute([$b]);foreach($st->fetchAll(PDO::FETCH_ASSOC) as $r)$old[(string)$r['item_key']=$r];$up=$db->prepare('INSERT INTO ds_rows(bucket,item_key,seq,payload) VALUES(?,?,?,?) ON CONFLICT(bucket,item_key) DO UPDATE SET seq=excluded.seq,payload=excluded.payload');$seen=[];if($kind==='map'){$payload=json_encode($x,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);if($payload===false)return false;$key='__map__';$seen[$key]=1;$before=(string)($old[$key]['payload']??'');$up->execute([$b,$key,0,$payload]);if($before!==$payload)ws_ledger($db,$b,$key,$before===''?'insert':'update',$before,$payload);}else{$i=0;foreach($x as $r){if(!is_array($r))continue;$key=ws_row_key($r,$i);while(isset($seen[$key]))$key.='_'.$i;$seen[$key]=1;$payload=json_encode($r,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);if($payload===false)return false;$before=(string)($old[$key]['payload']??'');$up->execute([$b,$key,$i++,$payload]);if($before!==$payload)ws_ledger($db,$b,$key,$before===''?'insert':'update',$before,$payload);}}
$del=$db->prepare('DELETE FROM ds_rows WHERE bucket=? AND item_key=?');foreach($old as $key=>$r)if(!isset($seen[$key])){$before=(string)($r['payload']??'');ws_ledger($db,$b,$key,'delete',$before,'');$del->execute([$b,$key]);}$db->prepare('INSERT INTO ds_meta(bucket,kind,updated_at) VALUES(?,?,?) ON CONFLICT(bucket) DO UPDATE SET kind=excluded.kind,updated_at=excluded.updated_at')->execute([$b,$kind,ws_now()]);return true;}
function ws_store_read(string $f):array{if(!ws_managed($f)||!($db=ws_db()))return ws_raw_read($f);$b=ws_bucket($f);try{$s=$db->prepare('SELECT kind FROM ds_meta WHERE bucket=?');$s->execute([$b]);$kind=$s->fetchColumn();if($kind===false){$legacy=ws_raw_read($f);ws_store_write($f,$legacy);return $legacy;}$s=$db->prepare('SELECT payload FROM ds_rows WHERE bucket=? ORDER BY seq');$s->execute([$b]);$rows=$s->fetchAll(PDO::FETCH_COLUMN);if($kind==='map'){if(!$rows)return [];$x=json_decode((string)$rows[0],true);return is_array($x)?$x:[];}$out=[];foreach($rows as $q){$x=json_decode((string)$q,true);if(is_array($x))$out[]=$x;}return $out;}catch(Throwable $e){return ws_raw_read($f);}}
function ws_store_write(string $f,array $x):bool{if(!ws_managed($f)||!($db=ws_db()))return ws_raw_write($f,$x);$own=!$db->inTransaction();try{if($own)$db->beginTransaction();$ok=ws_store_write_tx($db,$f,$x);if(!$ok)throw new RuntimeException('store_write_failed');if($own)$db->commit();return true;}catch(Throwable $e){if($own&&$db->inTransaction())$db->rollBack();return false;}}
function ws_backend():string{return ws_db()?'sqlite-wal':'json-fallback';}
function ws_phone(string $p):string{$d=preg_replace('/\D/','',$p)??'';if(str_starts_with($d,'0098'))$d=substr($d,4);elseif(str_starts_with($d,'98'))$d=substr($d,2);if(strlen($d)===10&&str_starts_with($d,'9'))$d='0'.$d;return strlen($d)===11&&str_starts_with($d,'09')?$d:'';}
function ws_contact_get(string $phone):?array{$p=ws_phone($phone);if($p==='')return null;if($db=ws_db()){try{$s=$db->prepare('SELECT * FROM contacts WHERE phone=?');$s->execute([$p]);$r=$s->fetch(PDO::FETCH_ASSOC);return is_array($r)?$r:null;}catch(Throwable $e){}}foreach(ws_raw_read(ws_dir().'/contact_registry.json') as $r)if(($r['phone']??'')===$p)return $r;return null;}
function ws_contact_seen(string $phone):bool{return ws_contact_get($phone)!==null;}
function ws_contact_touch_db(PDO $db,string $phone,array $m=[]):bool{$p=ws_phone($phone);if($p==='')return false;$n=ws_now();$st=(string)($m['status']??'');$lid=(string)($m['lead_id']??'');$biz=(string)($m['business']??'');$src=(string)($m['source']??'');$meta=json_encode($m,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?:'{}';$s=$db->prepare('INSERT INTO contacts(phone,first_seen_at,last_seen_at,last_status,last_lead_id,business,source,do_not_contact,contact_count,meta_json) VALUES(?,?,?,?,?,?,?,1,1,?) ON CONFLICT(phone) DO UPDATE SET last_seen_at=excluded.last_seen_at,last_status=CASE WHEN excluded.last_status<>"" THEN excluded.last_status ELSE contacts.last_status END,last_lead_id=CASE WHEN excluded.last_lead_id<>"" THEN excluded.last_lead_id ELSE contacts.last_lead_id END,business=CASE WHEN excluded.business<>"" THEN excluded.business ELSE contacts.business END,source=CASE WHEN excluded.source<>"" THEN excluded.source ELSE contacts.source END,do_not_contact=1,contact_count=contacts.contact_count+1,meta_json=excluded.meta_json');return $s->execute([$p,$n,$n,$st,$lid,$biz,$src,$meta]);}
function ws_contact_touch(string $phone,array $m=[]):bool{$p=ws_phone($phone);if($p==='')return false;if($db=ws_db()){try{return ws_contact_touch_db($db,$p,$m);}catch(Throwable $e){return false;}}$f=ws_dir().'/contact_registry.json';$rows=ws_raw_read($f);foreach($rows as &$r)if(($r['phone']??'')===$p){$r['last_seen_at']=ws_now();$r['contact_count']=(int)($r['contact_count']??0)+1;$r['meta']=$m;return ws_raw_write($f,$rows);}unset($r);$rows[]=['phone'=>$p,'first_seen_at'=>ws_now(),'last_seen_at'=>ws_now(),'last_status'=>(string)($m['status']??''),'last_lead_id'=>(string)($m['lead_id']??''),'business'=>(string)($m['business']??''),'source'=>(string)($m['source']??''),'do_not_contact'=>1,'contact_count'=>1,'meta'=>$m];return ws_raw_write($f,$rows);}
function ws_import_contacts(array $leads):int{$n=0;foreach($leads as $l){if(!is_array($l))continue;$p=ws_phone((string)($l['phone']??''));if($p!==''&&!ws_contact_seen($p)&&ws_contact_touch($p,['status'=>'historical','lead_id'=>(string)($l['id']??''),'business'=>(string)($l['business']??$l['name']??''),'source'=>(string)($l['source']??'legacy')]))$n++;}return $n;}
function ws_audit_db(PDO $db,string $kind,string $ref='',string $phone='',array $payload=[]):void{$s=$db->prepare('INSERT INTO audit(kind,ref_id,phone,payload,created_at) VALUES(?,?,?,?,?)');$s->execute([$kind,$ref,ws_phone($phone),json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?:'{}',ws_now()]);}
function ws_audit(string $kind,string $ref='',string $phone='',array $payload=[]):void{if(!($db=ws_db()))return;try{ws_audit_db($db,$kind,$ref,$phone,$payload);}catch(Throwable $e){}}
function ws_ingest_commit(string $leadFile,array $rows,array $contacts):bool{$db=ws_db();if($db&&ws_managed($leadFile)){try{$db->beginTransaction();if(!ws_store_write_tx($db,$leadFile,$rows))throw new RuntimeException('lead_write');foreach($contacts as $c){if(!is_array($c))continue;$phone=(string)($c['phone']??'');$meta=is_array($c['meta']??null)?$c['meta']:[];if(!ws_contact_touch_db($db,$phone,$meta))throw new RuntimeException('contact_write');ws_audit_db($db,'lead_ingested',(string)($meta['lead_id']??''),$phone,['score'=>(int)($meta['score']??0),'source'=>(string)($meta['source']??''),'city'=>(string)($meta['city']??'')]);}$db->commit();return true;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();return false;}}if(!ws_raw_write($leadFile,$rows))return false;foreach($contacts as $c)if(is_array($c))ws_contact_touch((string)($c['phone']??''),is_array($c['meta']??null)?$c['meta']:[]);return true;}
function ws_sms_settings(string $settingsFile):array{return ws_raw_read($settingsFile);}
function ws_sms_key(array $c):string{foreach(['sms_api_key','faraz_api_key','ippanel_api_key','api_key'] as $k){$v=trim((string)($c[$k]??''));if($v!=='')return $v;}foreach(['FARAZ_SMS_API_KEY','IPPANEL_API_KEY','SMS_API_KEY'] as $k){$v=getenv($k);if(is_string($v)&&trim($v)!=='')return trim($v);}return '';}
function ws_sms_send_now(string $settingsFile,string $mobile,string $pattern,array $attrs):array{$c=ws_sms_settings($settingsFile);if(array_key_exists('sms_enabled',$c)&&empty($c['sms_enabled']))return ['ok'=>false,'status'=>'disabled','http'=>0];$key=ws_sms_key($c);$to=ws_phone($mobile);$from=trim((string)($c['sms_sender']??$c['sms_from_number']??'90008361'));if($key===''||$to===''||trim($pattern)===''||!function_exists('curl_init'))return ['ok'=>false,'status'=>'not_configured','http'=>0];$payload=['code'=>trim($pattern),'attributes'=>(object)$attrs,'recipient'=>$to,'line_number'=>$from?:'90008361','number_format'=>'english'];$ch=curl_init('https://api.iranpayamak.com/ws/v1/sms/pattern');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($payload,JSON_UNESCAPED_UNICODE),CURLOPT_HTTPHEADER=>['Content-Type: application/json','Accept: application/json','Api-Key: '.$key],CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_TIMEOUT=>20,CURLOPT_IPRESOLVE=>CURL_IPRESOLVE_V4,CURLOPT_HTTP_VERSION=>CURL_HTTP_VERSION_1_1]);$out=(string)curl_exec($ch);$http=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);$err=(string)curl_error($ch);curl_close($ch);$j=json_decode($out,true);$ok=$http>=200&&$http<300&&$err===''&&(!is_array($j)||!isset($j['status'])||strtolower((string)$j['status'])==='success');return ['ok'=>$ok,'status'=>$ok?'accepted':'rejected','http'=>$http,'response'=>mb_substr($out,0,500),'error'=>$err];}
function ws_sms_enqueue(string $settingsFile,string $mobile,string $pattern,array $attrs,string $kind='',string $ref=''):array{$c=ws_sms_settings($settingsFile);if(array_key_exists('sms_enabled',$c)&&empty($c['sms_enabled']))return ['ok'=>false,'status'=>'disabled'];$to=ws_phone($mobile);$pattern=trim($pattern);if($to===''||$pattern===''||ws_sms_key($c)==='')return ['ok'=>false,'status'=>'not_configured'];$f=ws_dir().'/sms_queue.json';$q=ws_store_read($f);$dedupe=hash('sha256',$kind.'|'.$ref.'|'.$to.'|'.$pattern);foreach($q as $r)if(($r['dedupe_key']??'')===$dedupe&&in_array((string)($r['status']??''),['queued','retry','sent'],true))return ['ok'=>true,'status'=>(string)$r['status'],'id'=>(string)($r['id']??'')];$id='SMS'.bin2hex(random_bytes(6));$q[]=['id'=>$id,'dedupe_key'=>$dedupe,'kind'=>$kind,'ref'=>$ref,'mobile'=>$to,'pattern'=>$pattern,'attrs'=>$attrs,'status'=>'queued','attempts'=>0,'next_attempt_at'=>ws_now(),'provider_http'=>0,'provider_response'=>'','last_error'=>'','created_at'=>ws_now(),'sent_at'=>''];if(count($q)>30000)$q=array_slice($q,-30000);if(!ws_store_write($f,$q))return ['ok'=>false,'status'=>'queue_write_failed'];ws_audit('sms_queued',$ref,$to,['kind'=>$kind,'pattern'=>$pattern,'id'=>$id]);return ['ok'=>true,'status'=>'queued','id'=>$id];}
function ws_sms_pattern(string $settingsFile,string $mobile,string $pattern,array $attrs,string $kind='',string $ref=''):array{return ws_sms_enqueue($settingsFile,$mobile,$pattern,$attrs,$kind,$ref);}
function ws_sms_process_queue(string $settingsFile,int $limit=20):array{$f=ws_dir().'/sms_queue.json';$logf=ws_dir().'/sms_log.json';$q=ws_store_read($f);$logs=ws_store_read($logf);$now=time();$done=0;$sent=0;$retry=0;$dead=0;foreach($q as &$r){if($done>=$limit)break;$st=(string)($r['status']??'');if(!in_array($st,['queued','retry'],true))continue;$due=strtotime((string)($r['next_attempt_at']??''))?:0;if($due>$now)continue;$done++;$res=ws_sms_send_now($settingsFile,(string)($r['mobile']??''),(string)($r['pattern']??''),is_array($r['attrs']??null)?$r['attrs']:[]);$r['attempts']=(int)($r['attempts']??0)+1;$r['provider_http']=(int)($res['http']??0);$r['provider_response']=(string)($res['response']??'');$r['last_error']=(string)($res['error']??'');if(!empty($res['ok'])){$r['status']='sent';$r['sent_at']=ws_now();$sent++;}elseif($r['attempts']>=5){$r['status']='dead';$dead++;}else{$r['status']='retry';$delay=min(3600,60*(2**max(0,$r['attempts']-1)));$r['next_attempt_at']=date('Y-m-d H:i:s',$now+$delay);$retry++;}$logs[]=['id'=>'SL'.bin2hex(random_bytes(5)),'queue_id'=>(string)($r['id']??''),'kind'=>(string)($r['kind']??''),'ref'=>(string)($r['ref']??''),'mobile'=>(string)($r['mobile']??''),'pattern'=>(string)($r['pattern']??''),'status'=>(string)$r['status'],'http'=>(int)($r['provider_http']??0),'attempt'=>(int)$r['attempts'],'created_at'=>ws_now()];}unset($r);if($done){ws_store_write($f,$q);if(count($logs)>20000)$logs=array_slice($logs,-20000);ws_store_write($logf,$logs);}return ['processed'=>$done,'sent'=>$sent,'retry'=>$retry,'dead'=>$dead];}
function ws_score(array $l):int{$s=(int)($l['lead_score']??0);if($s>0)return max(0,min(100,$s));$s=50;$site=mb_strtolower((string)($l['website_status']??''),'UTF-8');if($site===''||str_contains($site,'ندارد')||str_contains($site,'بدون'))$s+=22;elseif(str_contains($site,'ضعیف')||str_contains($site,'قدیمی'))$s+=14;if(!empty($l['source_url']))$s+=5;if(!empty($l['social_url'])||!empty($l['instagram']))$s+=6;if(!empty($l['proposal']))$s+=6;if(!empty($l['evidence']))$s+=6;return max(0,min(100,$s));}
function ws_calibrated_score(array $l):int{$base=ws_score($l);static $cache=null;if($cache===null){$leads=ws_store_read(ws_dir().'/leads.json');$as=ws_store_read(ws_dir().'/assignments.json');$by=[];foreach($leads as $x)if(is_array($x)&&!empty($x['id']))$by[(string)$x['id']]=$x;$handled=0;$won=0;$cats=[];foreach($as as $a){if(!is_array($a))continue;$st=(string)($a['status']??'new');if(in_array($st,['new','reassigned'],true))continue;$handled++;if($st==='won')$won++;$ld=$by[(string)($a['lead_id']??'')]??null;if(!$ld)continue;$c=trim((string)($ld['category']??''));if($c==='')continue;$cats[$c]['h']=($cats[$c]['h']??0)+1;if($st==='won')$cats[$c]['w']=($cats[$c]['w']??0)+1;}$cache=['handled'=>$handled,'rate'=>$handled?$won/$handled:0.0,'cats'=>$cats];}if(($cache['handled']??0)<100)return $base;$c=trim((string)($l['category']??''));$x=$cache['cats'][$c]??null;if(!$x||($x['h']??0)<20)return $base;$delta=(int)round(((($x['w']??0)/max(1,$x['h']))-$cache['rate'])*20);$delta=max(-5,min(5,$delta));return max(0,min(100,$base+$delta));}
function ws_location_bonus(array $l,array $b):int{$lc=trim((string)($l['city']??''));$bc=trim((string)($b['city']??''));return $lc!==''&&$bc!==''&&mb_strtolower($lc,'UTF-8')===mb_strtolower($bc,'UTF-8')?5:0;}
function ws_health():array{$db=ws_db();$contacts=0;$sets=[];$integrity='unknown';$ledger=0;if($db){try{$contacts=(int)$db->query('SELECT COUNT(*) FROM contacts')->fetchColumn();$sets=$db->query('SELECT bucket,kind,updated_at FROM ds_meta ORDER BY bucket')->fetchAll(PDO::FETCH_ASSOC);$integrity=(string)$db->query('PRAGMA integrity_check')->fetchColumn();$ledger=(int)$db->query('SELECT COUNT(*) FROM finance_ledger')->fetchColumn();}catch(Throwable $e){$integrity='error';}}else{$contacts=count(ws_raw_read(ws_dir().'/contact_registry.json'));}$q=ws_store_read(ws_dir().'/sms_queue.json');$dead=0;$retry=0;foreach($q as $r){$st=(string)($r['status']??'');if($st==='dead')$dead++;elseif($st==='retry')$retry++;}return ['ok'=>$db!==null&&$integrity==='ok','version'=>'platform-v4','backend'=>ws_backend(),'contacts'=>$contacts,'datasets'=>$sets,'pdo_sqlite'=>class_exists('PDO')&&in_array('sqlite',PDO::getAvailableDrivers(),true),'integrity'=>$integrity,'ledger_entries'=>$ledger,'sms_dead'=>$dead,'sms_retry'=>$retry,'time'=>ws_now()];}
